namespace TownOfHost.Modules{public class PlayerGameOptionsSender{public PlayerControl player;public PreparedOptions cachedGameOptions;}public class PreparedOptions:AmongUs.GameOptions.IGameOptions{public float Speed;public float GetFloat(AmongUs.GameOptions.FloatOptionNames n)=>Speed;}public static class GameOptionsSender{public static List<object> AllSenders=new();public static int Flushes;public static Dictionary<byte,float> LastSent=new();public static void SendAllGameOptions(){Flushes++;foreach(var p in TownOfHost.PlayerCatch.Players.Values.ToArray()){if(!p.Dirty)continue;var sender=AllSenders.OfType<PlayerGameOptionsSender>().FirstOrDefault(s=>s.player==p);var speed=TownOfHost.RealSpeedPipeline.Build(sender?.player??p);LastSent[p.PlayerId]=speed;if(sender!=null)sender.cachedGameOptions=new(){Speed=speed};p.Dirty=false;}}}}
